CREATE OR REPLACE FUNCTION public.fn_get_journey_entry_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, child_id uuid, enrollment_id uuid, classroom_id uuid, teacher_id uuid, experience_id uuid, experience_schedule_id uuid, experience_session_id uuid, experience_participation_id uuid, little_moment_id uuid, milestone_id uuid, journey_type character varying, title character varying, observation text, child_voice text, teacher_reflection text, observation_date timestamp with time zone, participation_type character varying, is_milestone boolean, is_parent_visible boolean, parent_visibility_status character varying, created_at timestamp with time zone, created_by uuid, updated_at timestamp with time zone, updated_by uuid, version integer)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT cje.id, cje.tenant_id, cje.child_id, cje.enrollment_id, cje.classroom_id,            cje.teacher_id, cje.experience_id, cje.experience_schedule_id,            cje.experience_session_id, cje.experience_participation_id,            cje.little_moment_id, cje.milestone_id, cje.journey_type,            cje.title, cje.observation, cje.child_voice, cje.teacher_reflection,            cje.observation_date, cje.participation_type, cje.is_milestone,            cje.is_parent_visible, cje.parent_visibility_status,            cje.created_at, cje.created_by, cje.updated_at, cje.updated_by, cje.version     FROM child_journey_entries cje     WHERE cje.id = p_id AND cje.tenant_id = p_tenant_id; END; $function$ ;
